// Convierte la lista de la función 'renovaciones' en un correo por asesor.
// ===== CONFIGURA AQUÍ =====
const URL_RENOVAR = 'https://maximusinmobiliaria.tech/dashboard?renovar=1';
const URL_LOGO = 'https://maximusinmobiliaria.tech/assets/email/logo-maximus-email.png';
const WHATSAPP_SOPORTE = '584247835697';
// ==========================
const res = $input.first().json;
const lista = Array.isArray(res.items) ? res.items : [];
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const TZ = 'America/Caracas';
const diaCaracas = (d) => new Date(d).toLocaleDateString('en-CA', { timeZone: TZ }); // AAAA-MM-DD
const fecha = (d) => new Date(d).toLocaleDateString('es-VE', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric' });
const hora = (d) => new Date(d).toLocaleTimeString('es-VE', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });
const diasEntre = (a, b) => Math.round((Date.parse(b) - Date.parse(a)) / 86400000);

return lista
  .filter(x => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(String(x.email || '').trim()))
  .map(x => {
    const difDias = diasEntre(diaCaracas(Date.now()), diaCaracas(x.vence_at)); // días de calendario en Venezuela
    const hoyOManana = x.tipo === 'vence_hoy';
    const cuando = difDias <= 0 ? 'hoy' : (difDias === 1 ? 'mañana' : 'en ' + difDias + ' días');
    const base = {
      auth_id: x.auth_id, tipo: x.tipo, vence_at: x.vence_at,
      email: String(x.email).trim(), nombre: esc(x.nombre || 'Asesor'),
      url_renovar: URL_RENOVAR, logo_url: URL_LOGO, url_whatsapp: 'https://wa.me/' + WHATSAPP_SOPORTE,
    };
    if (!hoyOManana) {
      return { json: { ...base,
        asunto: '⏳ Tu membresía MAXIMUS Pro vence ' + cuando,
        preheader: 'Vence el ' + fecha(x.vence_at) + ' · renueva por US$ 4.99 y no pierdas el acceso',
        badge: '⏳ Aviso de renovación', badge_bg: '#ECFDF5', badge_borde: '#A7F3D0', badge_color: '#059669', acento: '#10B981',
        titulo: 'Tu membresía vence ' + cuando,
        mensaje: 'Tu membresía MAXIMUS Pro vence el ' + fecha(x.vence_at) + '. Renuévala ahora para seguir usando tu CRM, el cotizador y la carga de inmuebles sin interrupciones.',
        etiqueta_vence: 'Vence el', vence_texto: fecha(x.vence_at),
        perderas_titulo: 'Lo que mantienes al renovar',
      } };
    }
    return { json: { ...base,
      asunto: '⚠️ Tu membresía MAXIMUS Pro vence ' + (difDias <= 0 ? 'hoy' : 'mañana'),
      preheader: 'Vence ' + (difDias <= 0 ? 'hoy' : 'mañana') + ' a las ' + hora(x.vence_at) + ' · renueva para no perder el acceso',
      badge: '⚠ Vence ' + (difDias <= 0 ? 'hoy' : 'mañana'), badge_bg: '#FFFBEB', badge_borde: '#FDE68A', badge_color: '#B45309', acento: '#F59E0B',
      titulo: 'Tu membresía vence ' + (difDias <= 0 ? 'hoy' : 'mañana'),
      mensaje: 'Tu membresía MAXIMUS Pro vence ' + (difDias <= 0 ? 'hoy' : 'mañana') + ' a las ' + hora(x.vence_at) + '. Si no la renuevas, tu cuenta volverá al plan gratuito y perderás el acceso a las herramientas Pro.',
      etiqueta_vence: 'Vence', vence_texto: fecha(x.vence_at) + ', ' + hora(x.vence_at),
      perderas_titulo: 'Lo que perderás si no renuevas',
    } };
  });
